const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || item;
const suppliedSecret = headers['x-xvond-n8n-secret'] || headers['X-Xvond-N8N-Secret'];
const expectedSecret = $env.N8N_SHARED_SECRET;
const requestId = String(body.request_id || headers['x-xvond-request-id'] || '');
const action = String(body.action || '').trim();

if (!expectedSecret || suppliedSecret !== expectedSecret) {
  return [{ json: { success: false, request_id: requestId, action, data: null, error: 'Unauthorized workflow request' } }];
}

if (!requestId || !body.company_id || !body.agent_id || !action) {
  return [{ json: { success: false, request_id: requestId, action, data: null, error: 'Invalid workflow request contract' } }];
}

if (action === 'health_check') {
  return [{ json: { success: true, request_id: requestId, action, data: { status: 'ok', engine: 'workflow', company_id: body.company_id, agent_id: body.agent_id }, error: null } }];
}

return [{ json: { success: false, request_id: requestId, action, data: null, error: `Unsupported workflow action: ${action}` } }];
